def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_d_x_squared(x):
    if x == 1:
        return 1
    factors = get_prime_factorization(x)
    # If x = p1^a1 * p2^a2 * ..., then x^2 = p1^(2a1) * p2^(2a2) * ...
    # d(x^2) = (2a1 + 1) * (2a2 + 1) * ...
    divisor_count = 1
    for prime, exponent in factors.items():
        divisor_count *= (2 * exponent + 1)
    return divisor_count

max_d = 0
max_x = 0
limit = 1717

for x in range(1, limit + 1):
    d_x_sq = calculate_d_x_squared(x)
    if d_x_sq > max_d:
        max_d = d_x_sq
        max_x = x
    elif d_x_sq == max_d and x > max_x:
        # Tie-breaker, though typically the lower one is preferred in maximization problems, 
        # we stick to the largest x if there's a tie just to find the maximum value robustly.
        max_x = x

print(f"Maximum d(x^2) found: {max_d}")
print(f"Corresponding x: {max_x}")

def count_divisors(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    count = 1
    for exponent in factors.values():
        count *= (exponent + 1)
    return count

